// Generated by Claude/specs/courses-tools/sync-ielts-exams.js from Claude/specs/lxd-course-ielts-exams/exam-04/ (farin-lxd). Do not hand-edit.
(function(E){ const x = E["exam-04"] = E["exam-04"] || {units:{}}; (x.units = x.units || {})["x04-l1"] = {"id":"x04-l1","patterns":["L1-forms","PARA-time"],"title":{"en":"Listening Part 1: a survey form","tr":"Listening Part 1: bir anket formu","fa":"Listening Part 1: یک فرم نظرسنجی"},"objective":{"en":"In this lesson you will learn to complete a ten-question survey form with ONE WORD ONLY: write the word, never a number, choose what the person does now, and record their own opinion.","tr":"Bu derste on soruluk bir anket formunu ONE WORD ONLY ile doldurmayı öğreneceksin: sayıyı değil kelimeyi yazacak, kişinin şimdi yaptığını seçecek ve onun kendi görüşünü kaydedeceksin.","fa":"در این درس یاد می‌گیری یک فرم نظرسنجی ده‌سؤالی را با ONE WORD ONLY پر کنی: کلمه را بنویسی، هیچ‌وقت عدد را نه، کاری را انتخاب کنی که آن آدم الان می‌کند و نظر خودش را ثبت کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Listening Part 1: a survey form","tr":"Listening Part 1: bir anket formu","fa":"Listening Part 1: یک فرم نظرسنجی"},"objective":{"en":"In this lesson you will learn to complete a ten-question survey form with ONE WORD ONLY: write the word, never a number, choose what the person does now, and record their own opinion.","tr":"Bu derste on soruluk bir anket formunu ONE WORD ONLY ile doldurmayı öğreneceksin: sayıyı değil kelimeyi yazacak, kişinin şimdi yaptığını seçecek ve onun kendi görüşünü kaydedeceksin.","fa":"در این درس یاد می‌گیری یک فرم نظرسنجی ده‌سؤالی را با ONE WORD ONLY پر کنی: کلمه را بنویسی، هیچ‌وقت عدد را نه، کاری را انتخاب کنی که آن آدم الان می‌کند و نظر خودش را ثبت کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"10"},{"label":{"en":"Speakers","tr":"Konuşan","fa":"گوینده"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"1 word","tr":"1 kelime","fa":"۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a town-centre survey","tr":"Bu sınav: kent merkezi anketi","fa":"این آزمون: نظرسنجی مرکز شهر"},"intro":{"en":"Part 1 is an everyday conversation in which one person needs information. Surveys and official forms come up often: the interviewer asks the questions in the order of the form, and the answers are the other person’s facts and opinions.","tr":"Part 1, bir kişinin bilgiye ihtiyaç duyduğu günlük bir konuşmadır. Anketler ve resmî formlar sık çıkar: anketör soruları formun sırasıyla sorar, cevaplar karşıdaki kişinin bilgileri ve görüşleridir.","fa":"Part 1 یک گفتگوی روزمره است که در آن یک نفر به اطلاعات نیاز دارد. نظرسنجی و فرم‌های رسمی زیاد می‌آیند: پرسشگر سؤال‌ها را به ترتیب فرم می‌پرسد و جواب‌ها واقعیت‌ها و نظرهای طرف مقابل‌اند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x04-l1-ctx","exam":true,"patterns":["L1-forms","PARA-time"],"often":{"pattern":"L1-forms","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}},"title":{"en":"A street survey","tr":"Bir sokak anketi","fa":"یک نظرسنجی خیابانی"},"asks":{"en":"An interviewer stops a shopper in the town centre and fills in a survey form: his name, why he came, how he travelled, where he parks, what he thinks of the shops and the centre, and how he wants the results.","tr":"Bir anketör kent merkezinde bir alışverişçiyi durduruyor ve bir anket formu dolduruyor: adı, neden geldiği, nasıl geldiği, nereye park ettiği, mağazalar ve merkez hakkında ne düşündüğü ve sonuçları nasıl almak istediği.","fa":"یک پرسشگر در مرکز شهر یک خریدار را نگه می‌دارد و فرم نظرسنجی را پر می‌کند: اسمش، چرا آمده، چطور آمده، کجا پارک می‌کند، درباره‌ی مغازه‌ها و مرکز شهر چه فکر می‌کند و نتیجه‌ها را چطور می‌خواهد."},"fields":["Name","Age group","Reason for visit","Transport","Parking","Shops","Improvements","Main problem","Usual day","Results sent by"],"words":[{"a":"main reason","b":"really I came because","tr":"asıl neden","fa":"دلیل اصلی"},{"a":"appointment","b":"a time booked to see someone","tr":"randevu","fa":"نوبت، وقت قبلی"},{"a":"travel by","b":"come on / take","tr":"... ile gelmek","fa":"با ... آمدن"},{"a":"usually","b":"normally / always now","tr":"genellikle","fa":"معمولاً"},{"a":"multi-storey","b":"a car park with several floors","tr":"katlı otopark","fa":"پارکینگ طبقاتی"},{"a":"feels unsafe","b":"I don’t feel safe there","tr":"güvensiz hissettiriyor","fa":"حس ناامنی می‌دهد"},{"a":"chain stores","b":"big shops with branches everywhere","tr":"zincir mağazalar","fa":"فروشگاه‌های زنجیره‌ای"},{"a":"places to sit","b":"benches / seats","tr":"oturacak yerler","fa":"جای نشستن"},{"a":"the main problem","b":"what bothers me most","tr":"asıl sorun","fa":"مشکل اصلی"},{"a":"litter","b":"rubbish left on the ground","tr":"çöp, sokağa atılan atık","fa":"زباله‌ی ریخته‌شده"},{"a":"day off","b":"a day without work","tr":"izin günü","fa":"روز مرخصی"}],"traps":[{"en":"Numbers near the answer. With ONE WORD ONLY, a figure such as \"Gate 7\" or \"the 8.15 train\" cannot be the answer: listen for the word that fits the gap.","tr":"Cevabın yakınındaki sayılar. ONE WORD ONLY varken \"Gate 7\" ya da \"the 8.15 train\" gibi bir rakam cevap olamaz: boşluğa uyan kelimeyi dinle.","fa":"عددهای نزدیک جواب. وقتی ONE WORD ONLY است، رقمی مثل «Gate 7» یا «the 8.15 train» نمی‌تواند جواب باشد: به کلمه‌ای گوش بده که در جای خالی جا می‌شود."},{"en":"\"I used to... but now I...\" The form asks about now, so write what the person does now.","tr":"\"Eskiden... ama şimdi...\" Form şimdiyi sorar; kişinin şimdi yaptığını yaz.","fa":"«قبلاً... اما الان...». فرم درباره‌ی الان می‌پرسد، پس کاری را بنویس که آن آدم الان می‌کند."},{"en":"\"People always say it’s X, but for me...\" The form records this person’s opinion, not what people say.","tr":"\"İnsanlar hep X der ama bence...\" Form bu kişinin görüşünü kaydeder, insanların söylediğini değil.","fa":"«مردم همیشه می‌گویند X است، اما برای من...». فرم نظرِ همین آدم را ثبت می‌کند، نه حرف مردم را."}],"example":{"lines":[["Interviewer","How often do you visit the library?"],["Visitor","I used to go every week, but now I mostly read on my tablet, so it’s about once a month."]],"item":"Library visits: once a ___","answer":"month","why":{"en":"\"Every week\" was before. \"Now... about once a month.\"","tr":"\"Her hafta\" eskidendi. \"Şimdi... ayda bir kadar.\"","fa":"«هر هفته» مال قبل بود. «الان... حدود ماهی یک بار»."}}},{"id":"L1-forms","ctx":["L1-forms"],"title":{"en":"A survey or an official form","tr":"Bir anket ya da resmî bir form","fa":"نظرسنجی یا فرم رسمی"},"asks":{"en":"An interviewer asks a member of the public questions (a shopping, transport or customer survey), or an official takes details for a report or a registration. The form collects personal details, reasons, opinions and suggestions.","tr":"Bir anketör halktan birine sorular sorar (alışveriş, ulaşım ya da müşteri anketi) ya da bir görevli bir tutanak veya kayıt için bilgi alır. Form kişisel bilgileri, nedenleri, görüşleri ve önerileri toplar.","fa":"یک پرسشگر از یک نفر سؤال می‌پرسد (نظرسنجی خرید، حمل‌ونقل یا رضایت مشتری)، یا یک مأمور برای گزارش یا ثبت‌نام اطلاعات می‌گیرد. فرم مشخصات شخصی، دلیل‌ها، نظرها و پیشنهادها را جمع می‌کند."},"fields":["Name / age group","Occupation","Postcode","Reason for journey or visit","How often","What was good","What could be improved","Date and time of incident"],"words":[{"a":"occupation","b":"what do you do / I'm a","tr":"meslek","fa":"شغل"},{"a":"reason for visit","b":"why did you come / I'm here to","tr":"ziyaret nedeni","fa":"دلیل مراجعه"},{"a":"how often","b":"about twice a month","tr":"ne sıklıkta","fa":"هر چند وقت یک بار"},{"a":"satisfied","b":"happy with / pleased with","tr":"memnun","fa":"راضی"},{"a":"complaint","b":"what annoyed me was","tr":"şikâyet","fa":"شکایت"},{"a":"suggestion","b":"it would be better if","tr":"öneri","fa":"پیشنهاد"},{"a":"date of birth","b":"when were you born","tr":"doğum tarihi","fa":"تاریخ تولد"},{"a":"incident","b":"what happened","tr":"olay","fa":"حادثه"},{"a":"stolen","b":"someone took","tr":"çalınmış","fa":"دزدیده‌شده"},{"a":"registered","b":"your name is on our list","tr":"kayıtlı","fa":"ثبت‌شده"},{"a":"improve","b":"should be changed / make it better","tr":"iyileştirmek","fa":"بهتر کردن"},{"a":"means of transport","b":"I came by / I usually drive","tr":"ulaşım şekli","fa":"وسیله‌ی رفت‌وآمد"}],"traps":[{"en":"Opinion questions: the person first says what was fine, then what was wrong. The form usually asks for the problem.","tr":"Görüş soruları: kişi önce neyin iyi olduğunu, sonra neyin kötü olduğunu söyler. Form genellikle sorunu sorar.","fa":"سؤال‌های نظری: آدم اول می‌گوید چه چیزی خوب بود، بعد چه چیزی بد بود. فرم معمولاً مشکل را می‌پرسد."},{"en":"Personal details (age group, occupation, postcode) are said quickly and in passing.","tr":"Kişisel bilgiler (yaş grubu, meslek, posta kodu) hızlı ve laf arasında söylenir.","fa":"مشخصات شخصی (گروه سنی، شغل، کد پستی) سریع و در میان حرف گفته می‌شوند."},{"en":"Descriptions of a lost or stolen item: colour, size and material, then one detail is corrected.","tr":"Kayıp ya da çalınan bir eşyanın tarifi: renk, boyut ve malzeme; sonra bir ayrıntı düzeltilir.","fa":"توصیف یک وسیله‌ی گم‌شده یا دزدیده‌شده: رنگ، اندازه و جنس؛ بعد یکی از جزئیات اصلاح می‌شود."}],"example":{"lines":[["Interviewer","How was the journey overall?"],["Passenger","The seats were comfortable, and the staff were friendly."],["Passenger","The only thing was the wifi. It kept cutting out."]],"item":"Problem with the journey: the ___","answer":"wifi","why":{"en":"Seats and staff were positive. \"The only thing was\" introduces the problem: the wifi.","tr":"Koltuklar ve personel olumlu. \"The only thing was\" sorunu getiriyor: wifi.","fa":"صندلی‌ها و کارکنان مثبت بودند. «The only thing was» مشکل را معرفی می‌کند: wifi."}},"general":true,"patterns":["L1-forms"],"often":{"pattern":"L1-forms","n":6,"of":40,"label":{"en":"Comes up often in the real exam: 6 of the last 40 tests","tr":"Gerçek sınavda sık çıkar: son 40 sınavın 6’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۶ آزمون از ۴۰ آزمونِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"One form, ten gaps, one break","tr":"Bir form, on boşluk, bir ara","fa":"یک فرم، ده جای خالی، یک مکث"},"body":{"en":"All ten questions are on one form. You read Questions 1-5, listen, then have a short break to read Questions 6-10. The recording plays once and the answers come in the order of the form. Write ONE WORD ONLY: no numbers.","tr":"On sorunun hepsi tek bir formdadır. Soru 1-5’i okur, dinlersin, sonra Soru 6-10’u okumak için kısa bir ara verilir. Kayıt bir kez çalınır ve cevaplar formun sırasıyla gelir. ONE WORD ONLY yaz: sayı yok.","fa":"هر ده سؤال روی یک فرم‌اند. سؤال‌های ۱ تا ۵ را می‌خوانی، گوش می‌دهی و بعد یک مکث کوتاه برای خواندن سؤال‌های ۶ تا ۱۰ داری. فایل یک بار پخش می‌شود و جواب‌ها به ترتیب فرم می‌آیند. ONE WORD ONLY بنویس: عدد نه."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"The interviewer reads the form for you","tr":"Anketör formu senin için okur","fa":"پرسشگر فرم را برایت می‌خواند"},"steps":[{"en":"Read the labels on the form: they are the interviewer’s questions in short form.","tr":"Formdaki etiketleri oku: anketörün sorularının kısa hâlidir.","fa":"برچسب‌های فرم را بخوان: همان سؤال‌های پرسشگرند، به شکل کوتاه."},{"en":"When the interviewer asks the next question, move to the next line.","tr":"Anketör bir sonraki soruyu sorduğunda bir sonraki satıra geç.","fa":"وقتی پرسشگر سؤال بعدی را می‌پرسد، برو سراغ خط بعد."},{"en":"Listen for the speaker’s final answer: after \"but now\", \"really\" or \"for me\".","tr":"Konuşanın son cevabını dinle: \"but now\", \"really\" ya da \"for me\"den sonra.","fa":"به جواب نهایی گوینده گوش بده: بعد از «but now»، «really» یا «for me»."},{"en":"Copy a spelled name letter by letter, and check your spelling of ordinary words.","tr":"Harf harf söylenen ismi harf harf yaz ve sıradan kelimelerin yazımını kontrol et.","fa":"اسمی را که هجی می‌شود حرف به حرف بنویس و املای کلمه‌های معمولی را هم چک کن."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Before, now, and other people","tr":"Eskiden, şimdi ve başkaları","fa":"قبلاً، الان و آدم‌های دیگر"},"body":{"en":"Survey answers often change in the middle of a sentence. The shopper says what he used to do, what people usually think, or what he did today by chance, and then gives the real answer. Write only the answer that fits the label.","tr":"Anket cevapları çoğu zaman cümlenin ortasında değişir. Kişi eskiden ne yaptığını, insanların genelde ne düşündüğünü ya da bugün tesadüfen ne yaptığını söyler, sonra asıl cevabı verir. Yalnızca etikete uyan cevabı yaz.","fa":"جواب‌های نظرسنجی اغلب وسط جمله عوض می‌شوند. آن آدم می‌گوید قبلاً چه می‌کرد، مردم معمولاً چه فکر می‌کنند یا امروز اتفاقی چه کرد و بعد جواب اصلی را می‌دهد. فقط جوابی را بنویس که به برچسب می‌خورد."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One form gap, step by step","tr":"Bir form boşluğu, adım adım","fa":"یک جای خالی فرم، قدم به قدم"},"instruction":"Complete the form below. Write ONE WORD ONLY for each answer.","item":"Usual way of getting to work: by ___","lines":[["Interviewer","How do you usually get to work?"],["Resident","I drove for years, but since they opened the cycle path, I go by bike, unless it’s raining."]],"answer":"bike","walk":[{"en":"The label says \"usual\", so you want what he normally does now.","tr":"Etikette \"usual\" yazıyor; şimdi normalde ne yaptığını istiyorsun.","fa":"برچسب می‌گوید «usual»، پس چیزی را می‌خواهی که الان معمولاً می‌کند."},{"en":"\"I drove for years\" is the past.","tr":"\"Yıllarca araba kullandım\" geçmiş.","fa":"«سال‌ها رانندگی کردم» مال گذشته است."},{"en":"\"Since they opened the cycle path, I go by bike\": write bike.","tr":"\"Bisiklet yolunu açtıklarından beri bisikletle gidiyorum\": bike yaz.","fa":"«از وقتی مسیر دوچرخه را باز کردند با دوچرخه می‌روم»: بنویس bike."}]},"quick":{"prompt":"Form: \"Favourite place to relax: the ___ room\" (ONE WORD ONLY). You hear: \"People always expect me to say the kitchen, but actually I spend most time in the garden room.\" What do you write?","options":["kitchen","garden","room"],"correct":1,"why":{"en":"The kitchen is what people expect. \"Actually\" gives his answer, and \"room\" is already printed.","tr":"Mutfak insanların beklediği şey. \"Actually\" onun cevabını verir; \"room\" zaten yazılı.","fa":"آشپزخانه چیزی است که مردم انتظار دارند. «actually» جواب او را می‌دهد و «room» از قبل چاپ شده."}},"remember":{"en":"Follow the form line by line, write the word not the number, and choose the answer that fits now.","tr":"Formu satır satır takip et, sayıyı değil kelimeyi yaz ve şimdiye uyan cevabı seç.","fa":"فرم را خط به خط دنبال کن، کلمه را بنویس نه عدد را و جوابی را انتخاب کن که به الان می‌خورد."},"type":"explain","id":"c-x04-l1-e","course":"ielts-exams","exam":"exam-04","unit":"x04-l1"},"drill":{"type":"drill","skill":"listening","part":"Listening Part 1","title":{"en":"Brayford town-centre survey","tr":"Brayford kent merkezi anketi","fa":"نظرسنجی مرکز شهر بریفورد"},"timed":8,"ctx":["L1-forms"],"script":[{"who":"Interviewer","line":"Excuse me, have you got five minutes? I'm doing a survey for Brayford Town Council about the town centre."},{"who":"Shopper","line":"Er, yes, OK. As long as it's quick. My bus goes in twenty minutes."},{"who":"Interviewer","line":"It won't take long. Could I have your name first?"},{"who":"Shopper","line":"It's Graeme Petley."},{"who":"Interviewer","line":"Could you spell the surname for me?"},{"who":"Shopper","line":"P-E-T-L-E-Y."},{"who":"Interviewer","line":"And could I ask which age group you're in? We have under twenty-five, twenty-five to forty-four, and forty-five or over."},{"who":"Shopper","line":"I'm forty-one, so the middle one."},{"who":"Interviewer","line":"Thank you. And what's the main reason you've come into the town centre today?"},{"who":"Shopper","line":"Well, I'll probably do a bit of shopping while I'm here, but really I came in because I had an appointment at the dentist."},{"who":"Interviewer","line":"So the main reason is the dentist. And how did you travel here today?"},{"who":"Shopper","line":"I came on the bus, the number forty-seven. I normally drive, but my car's being repaired. The bus took about twenty-five minutes, which wasn't too bad."},{"who":"Interviewer","line":"I see. When you do drive in, where do you usually park?"},{"who":"Shopper","line":"I used to use the multi-storey on Market Street, but they put the prices up last year, so now I always use the station car park. It's a bit further to walk, but it's much cheaper."},{"who":"Interviewer","line":"And what do you think of the station car park?"},{"who":"Shopper","line":"Well, it's not expensive, and there are always spaces. The problem is that it's very dark. A lot of the lights don't work, and it doesn't feel safe in the evening."},{"who":"Interviewer","line":"So you'd say it's too dark."},{"who":"Shopper","line":"Yes, definitely."},{"who":"Interviewer","line":"Thanks. Now some questions about the shops. Which kind of shops do you visit most often when you come into town?"},{"who":"Shopper","line":"Not the big chain stores, really. I like the charity shops. There are five or six on the High Street now, and you can find some real bargains, especially books."},{"who":"Interviewer","line":"Charity shops. And is there anything you'd like to see more of in the town centre?"},{"who":"Shopper","line":"Hmm. More places to sit, I think. There used to be lots of benches round the fountain, but most of them were taken away when the square was redesigned. Older people especially need somewhere to rest."},{"who":"Interviewer","line":"More benches. What would you say is the main problem with the town centre at the moment?"},{"who":"Shopper","line":"People always say it's the traffic, but honestly, the traffic's much better since they made the High Street one-way. For me the main problem is the litter. There are never enough bins, and on Sunday mornings it looks terrible."},{"who":"Interviewer","line":"OK, litter. And which day of the week do you usually come into town?"},{"who":"Shopper","line":"It used to be Saturdays, but since I started my new job I work at weekends, so now it's usually Thursdays, my day off."},{"who":"Interviewer","line":"Thursday. Last question: the council will publish the results of the survey in the spring. Would you like a copy? We can send it by email or by post."},{"who":"Shopper","line":"By post, please. I hardly ever check my emails."},{"who":"Interviewer","line":"That's fine. We already have your name, so I'll just need your address at the end. Thank you very much for your time."},{"who":"Shopper","line":"No problem. Good luck with the survey."}],"form":{"title":"Brayford Town Centre Survey","lines":["Name: Graeme (1) ___","Age group: 25-44","Main reason for visit today: an appointment at the (2) ___","Travelled today by: (3) ___","Usually parks at: the (4) ___ car park","Opinion of car park: too (5) ___","Shops visited most often: (6) ___ shops","Would like more: (7) ___","Main problem in the town centre: (8) ___","Usual day for visiting the town centre: (9) ___","Survey results to be sent by: (10) ___"]},"groups":[{"instruction":"Questions 1-10. Complete the form below. Write ONE WORD ONLY for each answer.","qtype":"form","questions":[{"n":1,"kind":"gap","prompt":"Name: Graeme ___","accept":["Petley"],"limit":1,"evidence":"P-E-T-L-E-Y","why":{"en":"Spelled P-E-T-L-E-Y. Check the E after the L.","tr":"P-E-T-L-E-Y diye harf harf söyleniyor. L’den sonraki E’yi kontrol et.","fa":"حرف به حرف: P-E-T-L-E-Y. E بعد از L را چک کن."},"trap":["TR-spell"]},{"n":2,"kind":"gap","prompt":"Main reason for visit today: an appointment at the ___","accept":["dentist"],"limit":1,"evidence":"I had an appointment at the dentist","why":{"en":"Shopping is only \"probably\" and \"while I’m here\". \"Really I came in because I had an appointment at the dentist.\"","tr":"Alışveriş yalnızca \"muhtemelen\" ve \"buradayken\". \"Aslında dişçide randevum olduğu için geldim.\"","fa":"خرید فقط «احتمالاً» و «حالا که این‌جام» است. «در واقع آمدم چون نوبت دندان‌پزشکی داشتم»."},"trap":["TR-paraphrase","TR-selfcorrect"]},{"n":3,"kind":"gap","prompt":"Travelled today by: ___","accept":["bus"],"limit":1,"evidence":"I came on the bus, the number forty-seven","why":{"en":"\"I came on the bus, the number forty-seven.\" ONE WORD ONLY: write bus, not the number.","tr":"\"Otobüsle geldim, kırk yedi numara.\" ONE WORD ONLY: sayıyı değil bus yaz.","fa":"«با اتوبوس آمدم، شماره‌ی چهل‌وهفت». ONE WORD ONLY: بنویس bus، نه عدد را."},"trap":["TR-number"]},{"n":4,"kind":"gap","prompt":"Usually parks at: the ___ car park","accept":["station"],"limit":1,"evidence":"now I always use the station car park","why":{"en":"He \"used to use the multi-storey\", but \"now I always use the station car park\".","tr":"\"Eskiden katlı otoparkı kullanırdı\" ama \"şimdi hep istasyon otoparkını kullanıyorum\".","fa":"«قبلاً از پارکینگ طبقاتی استفاده می‌کرد» اما «الان همیشه از پارکینگ ایستگاه استفاده می‌کنم»."},"trap":["TR-selfcorrect"]},{"n":5,"kind":"gap","prompt":"Opinion of car park: too ___","accept":["dark"],"limit":1,"evidence":"it's very dark","why":{"en":"\"It’s not expensive... The problem is that it’s very dark.\"","tr":"\"Pahalı değil... Sorun çok karanlık olması.\"","fa":"«گران نیست... مشکل این است که خیلی تاریک است»."},"trap":["TR-paraphrase"]},{"n":6,"kind":"gap","prompt":"Shops visited most often: ___ shops","accept":["charity"],"limit":1,"evidence":"I like the charity shops","why":{"en":"\"Not the big chain stores... I like the charity shops.\" \"shops\" is printed.","tr":"\"Büyük zincir mağazalar değil... Ben hayır dükkânlarını seviyorum.\" \"shops\" yazılı.","fa":"«نه فروشگاه‌های زنجیره‌ای بزرگ... من مغازه‌های خیریه را دوست دارم». «shops» چاپ شده."},"trap":["TR-paraphrase"]},{"n":7,"kind":"gap","prompt":"Would like more: ___","accept":["benches"],"limit":1,"evidence":"More places to sit, I think","why":{"en":"\"More places to sit\": the benches were taken away. Plural.","tr":"\"Daha fazla oturacak yer\": banklar kaldırılmış. Çoğul.","fa":"«جای نشستن بیشتر»: نیمکت‌ها برداشته شده‌اند. جمع."},"trap":["TR-paraphrase"]},{"n":8,"kind":"gap","prompt":"Main problem in the town centre: ___","accept":["litter"],"limit":1,"evidence":"For me the main problem is the litter","why":{"en":"\"People always say it’s the traffic, but... for me the main problem is the litter.\"","tr":"\"İnsanlar hep trafik der ama... bence asıl sorun çöpler.\"","fa":"«مردم همیشه می‌گویند ترافیک است، اما... برای من مشکل اصلی زباله است»."},"trap":["TR-paraphrase","TR-selfcorrect"]},{"n":9,"kind":"gap","prompt":"Usual day for visiting the town centre: ___","accept":["Thursday","Thursdays"],"limit":1,"evidence":"now it's usually Thursdays","why":{"en":"Saturdays was before his new job. \"Now it’s usually Thursdays, my day off.\"","tr":"Cumartesi yeni işinden önceydi. \"Şimdi genelde perşembe, izin günüm.\"","fa":"شنبه مال قبل از کار جدیدش بود. «الان معمولاً پنجشنبه است، روز مرخصی‌ام»."},"trap":["TR-selfcorrect"]},{"n":10,"kind":"gap","prompt":"Survey results to be sent by: ___","accept":["post"],"limit":1,"evidence":"By post, please","why":{"en":"Email or post: \"By post, please. I hardly ever check my emails.\"","tr":"E-posta ya da posta: \"Postayla lütfen. E-postalarıma neredeyse hiç bakmıyorum.\"","fa":"ایمیل یا پست: «با پست، لطفاً. تقریباً هیچ‌وقت ایمیل‌هایم را نگاه نمی‌کنم»."},"trap":["TR-paraphrase"]}]}],"audio":{"voices":{"Announcer":{"accent":"British (standard Southern)","gender":"M","tts":{"engine":"kokoro","voice":"bm_george"},"role":"Recorded rubric"},"Interviewer":{"accent":"British (Southern English)","gender":"F","tts":{"engine":"kokoro","voice":"bf_emma"},"role":"Street-survey interviewer"},"Shopper":{"accent":"North American","gender":"M","tts":{"engine":"kokoro","voice":"am_puck"},"role":"Shopper who answers the survey"}},"sequence":[{"type":"announcer","text":"Part 1. You will hear a woman who is carrying out a survey in a town centre talking to a man who is shopping there. First, you have some time to look at Questions 1 to 5."},{"type":"pause","seconds":30,"note":"reading time, Questions 1-5"},{"type":"announcer","text":"Now listen carefully and answer Questions 1 to 5."},{"type":"lines","from":0,"to":17,"note":"outdoor street: light traffic and footsteps, low"},{"type":"announcer","text":"Before you hear the rest of the conversation, you have some time to look at Questions 6 to 10."},{"type":"pause","seconds":30,"note":"reading time, Questions 6-10"},{"type":"announcer","text":"Now listen and answer Questions 6 to 10."},{"type":"lines","from":18,"to":29},{"type":"announcer","text":"That is the end of Part 1. You now have half a minute to check your answers.","after":30}]},"id":"c-x04-l1-d","course":"ielts-exams","exam":"exam-04","unit":"x04-l1"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"A \"multi-storey\" is a car park that...","options":["has several floors","is outside the town","is only for staff"],"correct":0,"why":{"en":"A storey is a floor of a building; multi-storey = with many floors.","tr":"Storey bir binanın katıdır; multi-storey = çok katlı.","fa":"storey یعنی طبقه‌ی ساختمان؛ multi-storey یعنی چندطبقه."}},{"tests":"paraphrase","point":1,"prompt":"Which word means \"rubbish left on the ground\"?","options":["luggage","leftovers","litter"],"correct":2,"why":{"en":"Litter = rubbish dropped in public places.","tr":"Litter = kamuya açık yerlere atılan çöp.","fa":"litter یعنی زباله‌ای که در جاهای عمومی ریخته می‌شود."}},{"tests":"method","point":2,"prompt":"The interviewer says \"Now some questions about the shops.\" What should you do?","options":["Go back and check your spelling","Move to the part of the form about shops","Stop writing until the end"],"correct":1,"why":{"en":"The interviewer follows the form: this sentence tells you the next section has started.","tr":"Anketör formu izler: bu cümle bir sonraki bölümün başladığını söyler.","fa":"پرسشگر فرم را دنبال می‌کند: این جمله می‌گوید بخش بعدی شروع شده."}},{"tests":"trap","point":3,"prompt":"Form: \"Usually shops on: ___\" (ONE WORD ONLY). You hear: \"I used to come on Mondays, but these days it’s Fridays.\" What do you write?","options":["Friday","Monday","Monday and Friday"],"correct":0,"why":{"en":"Mondays was before. \"These days it’s Fridays\" is the usual day now.","tr":"Pazartesi eskidendi. \"Bu aralar cuma\" şimdiki olağan gün.","fa":"دوشنبه مال قبل بود. «این روزها جمعه است» روز معمولِ الان است."}},{"tests":"trap","point":1,"prompt":"Form: \"Travelled by: ___\" (ONE WORD ONLY). You hear: \"I took the 7.40 train.\" What do you write?","options":["7.40","7.40 train","train"],"correct":2,"why":{"en":"ONE WORD ONLY allows no numbers: write train.","tr":"ONE WORD ONLY sayıya izin vermez: train yaz.","fa":"ONE WORD ONLY عدد را قبول نمی‌کند: بنویس train."}}],"id":"c-x04-l1-x","course":"ielts-exams","exam":"exam-04","unit":"x04-l1"}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
